import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { Request, Response } from 'express';
import pdfParse from 'pdf-parse';
import multer from 'multer';

export const upload = multer({ 
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    if (file.mimetype === 'application/pdf') {
      cb(null, true);
    } else {
      cb(new Error('Only PDF files are allowed'));
    }
  }
});

export async function handleResumeUpload(req: Request, res: Response): Promise<void> {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF file uploaded.' });
      return;
    }

    const parsedPdf = await pdfParse(req.file.buffer);
    const resumeText = parsedPdf.text;

    const { jobDescription } = req.body;
    if (!jobDescription) {
      res.status(400).json({ error: 'Job description is required for matching.' });
      return;
    }

    // Simple keyword extraction and match scoring algorithm
    const cleanText = (text: string) => text.toLowerCase().match(/\b[a-z]{3,}\b/g) || [];
    const resumeWords = new Set(cleanText(resumeText));
    const jdWords = Array.from(new Set(cleanText(jobDescription)));

    const matchedKeywords: string[] = [];
    const missingKeywords: string[] = [];

    jdWords.forEach(word => {
      if (resumeWords.has(word)) {
        matchedKeywords.push(word);
      } else {
        missingKeywords.push(word);
      }
    });

    const matchScore = Math.round((matchedKeywords.length / (jdWords.length || 1)) * 100);

    res.status(200).json({
      matchScore,
      breakdown: {
        matched: matchedKeywords.slice(0, 30),
        missing: missingKeywords.slice(0, 30),
        totalMatchedCount: matchedKeywords.length,
        totalMissingCount: missingKeywords.length
      }
    });
  } catch (error) {
    res.status(500).json({ error: 'Failed to parse PDF resume.' });
  }
}

import React from 'react';

interface MatchScoreGaugeProps {
  score: number;
}

export const MatchScoreGauge: React.FC<MatchScoreGaugeProps> = ({ score }) => {
  const radius = 54;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (score / 100) * circumference;

  const getColor = (s: number) => {
    if (s >= 80) return 'text-emerald-500';
    if (s >= 50) return 'text-amber-500';
    return 'text-rose-500';
  };

  return (
    <div className="flex flex-col items-center justify-center p-6 bg-slate-900 rounded-2xl border border-slate-800 shadow-xl">
      <div className="relative flex items-center justify-center">
        <svg className="w-36 h-36 transform -rotate-90">
          <circle
            cx="72"
            cy="72"
            r={radius}
            className="text-slate-800"
            strokeWidth="12"
            stroke="currentColor"
            fill="transparent"
          />
          <circle
            cx="72"
            cy="72"
            r={radius}
            className={`transition-all duration-1000 ease-out ${getColor(score)}`}
            strokeWidth="12"
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
            stroke="currentColor"
            fill="transparent"
          />
        </svg>
        <div className="absolute flex flex-col items-center">
          <span className="text-3xl font-extrabold text-white">{score}%</span>
          <span className="text-xs font-medium text-slate-400">Match Score</span>
        </div>
      </div>
      <p className="mt-4 text-sm text-slate-300 font-medium text-center">
        {score >= 80 ? 'Excellent match for ATS optimization!' : score >= 50 ? 'Moderate match, add missing keywords.' : 'Low match, significant revisions recommended.'}
      </p>
    </div>
  );
};
